CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, username VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations (id CHAR(36) PRIMARY KEY, user_id CHAR(36), title VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id));
CREATE TABLE IF NOT EXISTS messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, conversation_id CHAR(36) NOT NULL, role ENUM('system','user','assistant','tool') NOT NULL, content LONGTEXT NOT NULL, model VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(conversation_id));
CREATE TABLE IF NOT EXISTS agents (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, system_prompt LONGTEXT, enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_runs (id CHAR(36) PRIMARY KEY, agent_id CHAR(36), task TEXT NOT NULL, status ENUM('queued','running','success','failed','paused') DEFAULT 'queued', result_json JSON, started_at TIMESTAMP NULL, finished_at TIMESTAMP NULL, INDEX(agent_id));
CREATE TABLE IF NOT EXISTS workflows (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, definition_json JSON NOT NULL, version INT DEFAULT 1, enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflow_runs (id CHAR(36) PRIMARY KEY, workflow_id CHAR(36), status ENUM('queued','running','success','failed','paused') DEFAULT 'queued', state_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(workflow_id));
CREATE TABLE IF NOT EXISTS memories (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id CHAR(36), memory_key VARCHAR(255) NOT NULL, memory_value LONGTEXT NOT NULL, embedding_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), INDEX(memory_key));
CREATE TABLE IF NOT EXISTS tool_executions (id BIGINT AUTO_INCREMENT PRIMARY KEY, agent_run_id CHAR(36), tool_name VARCHAR(120) NOT NULL, risk_level ENUM('read','low','medium','high','critical') DEFAULT 'low', input_json JSON, output_json JSON, approved BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(agent_run_id));
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(255), action VARCHAR(120) NOT NULL, resource VARCHAR(255), payload_json JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
